CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),steam_id text UNIQUE,display_name text NOT NULL,avatar_url text,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','cooldown','banned')),rating integer NOT NULL DEFAULT 1000,trust_score integer NOT NULL DEFAULT 100 CHECK(trust_score BETWEEN 0 AND 100),region text NOT NULL DEFAULT 'EU West',is_bot boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz);
CREATE INDEX IF NOT EXISTS players_status_idx ON players(status);CREATE INDEX IF NOT EXISTS players_is_bot_idx ON players(is_bot);
CREATE TABLE IF NOT EXISTS player_roles(player_id uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('Carry','Mid','Offlane','Soft Support','Hard Support')),priority integer NOT NULL DEFAULT 1,PRIMARY KEY(player_id,role));
CREATE TABLE IF NOT EXISTS queue_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,region text NOT NULL,primary_role text NOT NULL,secondary_role text NOT NULL,rating_snapshot integer NOT NULL,trust_score_snapshot integer NOT NULL,status text NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','matched','cancelled','expired')),joined_at timestamptz NOT NULL DEFAULT now(),matched_at timestamptz,cancelled_at timestamptz,version integer NOT NULL DEFAULT 1,CHECK(primary_role<>secondary_role));
CREATE UNIQUE INDEX IF NOT EXISTS queue_one_active_per_player ON queue_entries(player_id) WHERE status='waiting';CREATE INDEX IF NOT EXISTS queue_waiting_idx ON queue_entries(region,status,joined_at);
CREATE TABLE IF NOT EXISTS matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_code text NOT NULL UNIQUE,region text NOT NULL,status text NOT NULL DEFAULT 'accepting' CHECK(status IN ('accepting','ready','connecting','in_progress','completed','cancelled','expired')),accept_deadline timestamptz NOT NULL,started_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,winner text CHECK(winner IS NULL OR winner IN ('radiant','dire')),radiant_score integer NOT NULL DEFAULT 0,dire_score integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS matches_status_idx ON matches(status);
CREATE TABLE IF NOT EXISTS match_players(match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,team text NOT NULL CHECK(team IN ('radiant','dire')),role text NOT NULL CHECK(role IN ('Carry','Mid','Offlane','Soft Support','Hard Support')),accept_status text NOT NULL DEFAULT 'pending' CHECK(accept_status IN ('pending','accepted','declined','timeout')),rating_before integer NOT NULL,rating_after integer,trust_score_before integer NOT NULL,trust_score_after integer,joined_at timestamptz NOT NULL DEFAULT now(),accepted_at timestamptz,PRIMARY KEY(match_id,player_id));CREATE INDEX IF NOT EXISTS match_players_player_idx ON match_players(player_id);
CREATE TABLE IF NOT EXISTS rating_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),match_id uuid REFERENCES matches(id),reason text NOT NULL,delta integer NOT NULL,value_before integer NOT NULL,value_after integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trust_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),match_id uuid REFERENCES matches(id),reason text NOT NULL,delta integer NOT NULL,value_before integer NOT NULL,value_after integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS runtime_config(key text PRIMARY KEY,value jsonb NOT NULL,description text NOT NULL,is_public boolean NOT NULL DEFAULT false,updated_by text NOT NULL DEFAULT 'system',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feature_flags(key text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,description text NOT NULL,updated_by text NOT NULL DEFAULT 'system',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version text NOT NULL UNIQUE,title text NOT NULL,summary text NOT NULL,changelog jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sanctions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),type text NOT NULL,reason text NOT NULL,expires_at timestamptz,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);CREATE INDEX IF NOT EXISTS sanctions_active_idx ON sanctions(player_id,revoked_at);
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_type text NOT NULL,actor_id text NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,old_value jsonb,new_value jsonb,ip_address text,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at);
